items.solution_code:
numbers = [1, 2, 2, 3, 4, 4]

result = {x for x in numbers if x > 2}

print('Unique values above 2:', result)

# Avoid mutable default arguments
def make_set(items=None):
    if items is None:
        items = []
    return {item for item in items}

print(make_set([5, 5, 6]))

